int numDistinct(char *s, char *t) {
  int n = (int)strlen(s);
  int m = (int)strlen(t);

  unsigned long long *dp = (unsigned long long *)calloc(m + 1, sizeof(unsigned long long));
  dp[0] = 1;

  for (int i = 0; i < n; i++) {
    for (int j = m; j >= 1; j--) {
      if (s[i] == t[j - 1]) {
        dp[j] += dp[j - 1];
      }
    }
  }

  int ans = (int)dp[m];
  free(dp);
  return ans;
}

class Solution {
public:
  int numDistinct(string s, string t) {
    int m = t.size();
    vector<unsigned long long> dp(m + 1, 0);
    dp[0] = 1;
    for (char c : s) {
      for (int j = m; j >= 1; j--) {
        if (c == t[j - 1]) {
          dp[j] += dp[j - 1];
        }
      }
    }
    return (int)dp[m];
  }
};

