class Solution {
  public int numDistinct(String s, String t) {
    int m = t.length();
    long[] dp = new long[m + 1];
    dp[0] = 1;
    for (int i = 0; i < s.length(); i++) {
      for (int j = m; j >= 1; j--) {
        if (s.charAt(i) == t.charAt(j - 1)) {
          dp[j] += dp[j - 1];
        }
      }
    }
    return (int) dp[m];
  }
}

class Solution:
    def numDistinct(self, s: str, t: str) -> int:
        m = len(t)
        dp = [0] * (m + 1)
        dp[0] = 1
        for ch in s:
            for j in range(m, 0, -1):
                if ch == t[j - 1]:
                    dp[j] += dp[j - 1]
        return dp[m]

impl Solution {
  pub fn num_distinct(s: String, t: String) -> i32 {
    let t: Vec<char> = t.chars().collect();
    let m = t.len();
    let mut dp = vec![0u64; m + 1];
    dp[0] = 1;
    for c in s.chars() {
      for j in (1..=m).rev() {
        if c == t[j - 1] {
          dp[j] += dp[j - 1];
        }
      }
    }
    dp[m] as i32
  }
}

const numDistinct = (s: string, t: string): number => {
  const m = t.length;
  const dp: number[] = new Array(m + 1).fill(0);
  dp[0] = 1;
  for (const c of s) {
    for (let j = m; j >= 1; j--) {
      if (c === t[j - 1]) {
        dp[j] += dp[j - 1];
      }
    }
  }
  return dp[m];
};
